'use strict';(()=>{const view=document.getElementById('view'),toolbar=document.getElementById('toolbar'),workspace=document.getElementById('workspace'),label=document.getElementById('routeLabel'),status=document.getElementById('status');let serial=0;async function read(path,kind='json'){const r=await fetch(path);if(!r.ok)throw Error('Unable to load '+path);return kind==='json'?r.json():r.text();}function clearViewParameters(){const u=new URL(location.href);u.search='';history.replaceState(null,'',u);}function go(route){clearViewParameters();if(location.hash.slice(1)===route)render();else location.hash=route;}window.WBVault={json:name=>read('data/'+name+'.json'),blob:async name=>'data/'+name,text:name=>read(name,'text'),go,clearViewParameters,ready:()=>{},status:message=>{status.textContent=message;status.style.display=message?'block':'none';}};async function render(){const ticket=++serial,route=location.hash.slice(1)||'home',page=route==='home'?'home':route.startsWith('analysis')?'analysis':'map',choice=route.includes('corridor')?'corridor':'borderland';window.UNDPRouter={route,choice};toolbar.hidden=page==='home';workspace.classList.toggle('standalone',page==='home');workspace.classList.toggle('analysis-route',page==='analysis');label.hidden=false;label.textContent=page==='map'?'UNDP · Map':'UNDP · Analysis';view.title=page==='map'?'Tajikistan–Kyrgyzstan map':page==='home'?'UNDP maps homepage':'UNDP regional analysis';view.setAttribute('data-loading','');status.textContent='Opening '+page+'…';status.style.display='block';try{const html=await read('pages/'+page+'.html','text');if(ticket!==serial)return;view.onload=()=>{view.removeAttribute('data-loading');status.style.display='none';};view.srcdoc=html;}catch(e){status.textContent='This page could not be loaded. Please reload to retry.';console.error(e);}}window.addEventListener('hashchange',render);render();})();